import io
import unittest
from contextlib import redirect_stdout
from amount import format_amount, main


class AmountTests(unittest.TestCase):
    def test_regular(self):
        self.assertEqual(format_amount(125), "$1.25")

    def test_refund(self):
        self.assertEqual(format_amount(125, refund=True), "-$1.25")

    def test_cli_refund(self):
        output = io.StringIO()
        with redirect_stdout(output):
            main(["125", "--refund"])
        self.assertEqual(output.getvalue().strip(), "-$1.25")


if __name__ == "__main__":
    unittest.main()
